import { Finding } from '@sanity-labs/lint-core';

/**
 * Types for @sanity-labs/groq-wasm
 *
 * These types match the Rust API from groq-lint and groq-format,
 * converted to TypeScript conventions (snake_case → camelCase).
 */
/**
 * Severity levels matching Rust groq-lint
 * Rust: High, Medium, Low → TS: error, warning, info
 */
type WasmSeverity = 'high' | 'medium' | 'low';
/**
 * Map WASM severity to our standard severity
 */
declare function mapSeverity(wasmSeverity: WasmSeverity): 'error' | 'warning' | 'info';
/**
 * A finding from the Rust linter (JSON format from WASM)
 */
interface WasmFinding {
    /** Rule ID (snake_case from Rust) */
    ruleId: string;
    /** Human-readable message */
    message: string;
    /** Severity level */
    severity: WasmSeverity;
    /** Start offset into the UTF-8 encoding of the query (0-based) */
    start: number;
    /** End offset into the UTF-8 encoding of the query (0-based, exclusive) */
    end: number;
}
/**
 * Configuration for linting
 */
interface WasmLintConfig {
    /** Rules to enable/disable (rule_id → enabled) */
    rules?: Record<string, boolean>;
}
/**
 * Configuration for formatting
 */
interface WasmFormatConfig {
    /** Maximum line width (default: 80) */
    width?: number;
}
/**
 * One `$name` reference in a query, from {@link extractParams}.
 *
 * `start` and `end` are indices into the JavaScript query string (UTF-16 code
 * units), not UTF-8 byte offsets. `start` is inclusive and `end` is exclusive,
 * so `query.slice(start, end)` is `"$name"`. Lines and columns are 1-based,
 * and columns count UTF-16 code units, matching `SourceLocation` on lint
 * findings.
 */
interface ParamReference {
    /** Inclusive start index of the `$`, 0-based UTF-16 code units. */
    start: number;
    /** Exclusive end index, 0-based UTF-16 code units. */
    end: number;
    /** 1-based line number of `start`. */
    line: number;
    /** 1-based column of `start`, counted in UTF-16 code units. */
    column: number;
    /** 1-based line number of `end`. */
    endLine: number;
    /** 1-based column of `end`, counted in UTF-16 code units. */
    endColumn: number;
}
/**
 * A query parameter referenced by a GROQ query, from {@link extractParams}.
 */
interface QueryParam {
    /** Parameter name without the `$`, e.g. `"type"` for `$type`. */
    name: string;
    /** Every reference to this parameter, in source order. Never empty. */
    references: ParamReference[];
}
/**
 * Error from WASM operations
 */
declare class WasmError extends Error {
    readonly code: 'PARSE_ERROR' | 'WASM_ERROR';
    constructor(message: string, code: 'PARSE_ERROR' | 'WASM_ERROR');
}
/**
 * Rule ID mapping from Rust (snake_case) to TS (kebab-case)
 */
declare const RULE_ID_MAP: Record<string, string>;
/**
 * Convert Rust rule ID to TS convention
 */
declare function mapRuleId(rustRuleId: string): string;
/**
 * A GROQ syntax error from `validate`.
 *
 * `start` and `end` are indices into the JavaScript query string (UTF-16 code
 * units), not UTF-8 byte offsets. `start` is inclusive and `end` is exclusive,
 * so `query.slice(start, end)` is the reported span. groq-parser reports UTF-8
 * byte offsets; `validate` converts them. A zero-width span (`start === end`)
 * is a caret on a token boundary.
 *
 * `line` / `column` locate `start`, and `endLine` / `endColumn` locate `end`.
 * Lines and columns are 1-based. Columns count UTF-16 code units, matching
 * `SourceLocation` on lint findings.
 */
interface ValidateError {
    /** Parser message, without a serialized position suffix. */
    message: string;
    /** Inclusive start index, 0-based UTF-16 code units. */
    start: number;
    /** Exclusive end index, 0-based UTF-16 code units. */
    end: number;
    /** 1-based line number of `start`. */
    line: number;
    /** 1-based column of `start`, counted in UTF-16 code units. */
    column: number;
    /** 1-based line number of `end`. */
    endLine: number;
    /** 1-based column of `end`, counted in UTF-16 code units. */
    endColumn: number;
}
/**
 * Result of {@link validate}.
 *
 * Syntax errors are values, not thrown exceptions. `lint` and `format` still
 * throw {@link WasmError} when a query does not parse.
 */
type ValidateResult = {
    ok: true;
} | {
    ok: false;
    error: ValidateError;
};

/**
 * GROQ query parameter extraction via WASM.
 *
 * Wraps groq-parser's `ParseResult::referenced_params`. The parser reports
 * UTF-8 byte offsets; this module converts them to UTF-16 code unit indices.
 */

/**
 * List the query parameters (`$name`) a GROQ query references.
 *
 * Returns one entry per distinct name, in order of first reference. Each entry
 * lists every reference to that name in source order. Names do not include
 * the `$`, so they match the keys of the params object passed to a client.
 *
 * Parameters bound by a custom function (`fn ns::f($p) = ...`) are local to
 * that function's body and are not reported from inside it. `$name` text
 * inside string literals and comments is not a reference.
 *
 * Reference `start` / `end` are 0-based UTF-16 code unit indices into
 * `query` (`end` is exclusive), so `query.slice(start, end)` is `"$name"`.
 *
 * An empty or whitespace-only query returns `[]`, like `lint('')`.
 *
 * @param query - The GROQ query string
 * @returns Referenced parameters, in order of first reference
 * @throws {WasmError} With code `PARSE_ERROR` if the query does not parse
 *
 * @example
 * ```typescript
 * import {extractParams} from '@sanity-labs/groq-wasm'
 *
 * extractParams('*[_type == $type][0...$limit]').map((param) => param.name)
 * // ['type', 'limit']
 * ```
 */
declare function extractParams(query: string): QueryParam[];

/**
 * GROQ Linting via WASM
 *
 * Wraps the Rust groq-lint library compiled to WASM.
 */

/**
 * Lint a GROQ query using the WASM-based linter.
 *
 * Finding spans are source locations in JavaScript string coordinates.
 * The Rust linter reports UTF-8 byte offsets; `line`, `column`, and `offset`
 * below are converted from those bytes. `column` counts UTF-16 code units.
 *
 * @param query - The GROQ query string to lint
 * @param config - Optional configuration
 * @returns Array of findings
 * @throws {WasmError} If query parsing fails
 *
 * @example
 * ```typescript
 * import {lint} from '@sanity-labs/groq-wasm'
 *
 * const findings = lint('*[_type == "post"]{ author-> }')
 * // [{ ruleId: 'join-in-filter', message: '...', severity: 'error' }]
 * ```
 */
declare function lint(query: string, config?: WasmLintConfig): Finding[];

/**
 * GROQ Formatting via WASM
 *
 * Wraps the Rust groq-format library compiled to WASM.
 */

/**
 * Default line width for formatting
 * Matches Rust groq-format DEFAULT_WIDTH
 */
declare const DEFAULT_WIDTH = 80;
/**
 * Format a GROQ query using the WASM-based formatter
 *
 * @param query - The GROQ query string to format
 * @param config - Optional configuration (width defaults to 80)
 * @returns Formatted query string
 * @throws {WasmError} If query parsing fails
 *
 * @example
 * ```typescript
 * import {format} from '@sanity-labs/groq-wasm'
 *
 * const formatted = format('*[_type=="post"]{title,body}')
 * // '*[_type == "post"]{ title, body }'
 * ```
 */
declare function format(query: string, config?: WasmFormatConfig): string;
/**
 * Check if a query can be parsed (without full formatting)
 *
 * @param query - The GROQ query to validate
 * @returns true if the query is valid GROQ syntax
 */
declare function isValidSyntax(query: string): boolean;

/**
 * GROQ syntax validation via WASM.
 *
 * Wraps groq-parser's structured parse errors. The parser reports UTF-8 byte
 * offsets; this module converts them to UTF-16 code unit indices.
 */

/**
 * Parse a GROQ query.
 *
 * Returns `{ok: true}` when the query parses. Syntax errors are returned as
 * `{ok: false, error}` and are not thrown. `lint` and `format` still throw
 * {@link WasmError} on invalid syntax; this function does not change that.
 *
 * `error.start` and `error.end` are 0-based UTF-16 code unit indices into
 * `query` (`end` is exclusive), which is what JavaScript strings and editors
 * such as Vision use. groq-parser's `ParseError` positions are UTF-8 byte
 * offsets (`Position.start` / `Position.end` in groq-parser-rs). An empty or
 * whitespace-only query is a syntax error (`"no query"`) at offset 0, unlike
 * `lint('')` and `format('')`, which treat it as nothing to do.
 *
 * `line` / `column` locate `start`, and `endLine` / `endColumn` locate `end`.
 * They are 1-based. Columns count UTF-16 code units, matching `SourceLocation`
 * on lint findings.
 *
 * Parameter references (`$name`) are accepted. This is a syntax check and does
 * not require the parameters to be declared.
 *
 * @example
 * ```typescript
 * import {validate} from '@sanity-labs/groq-wasm'
 *
 * validate('*[_type == "post"]')
 * // {ok: true}
 *
 * validate('*["é" == ]')
 * // {
 * //   ok: false,
 * //   error: {
 * //     message: 'unexpected token "]", expected expression',
 * //     start: 9,
 * //     end: 10,
 * //     line: 1,
 * //     column: 10,
 * //     endLine: 1,
 * //     endColumn: 11,
 * //   },
 * // }
 * ```
 */
declare function validate(query: string): ValidateResult;

export { DEFAULT_WIDTH, RULE_ID_MAP, WasmError, extractParams, format, isValidSyntax, lint, mapRuleId, mapSeverity, validate };
export type { ParamReference, QueryParam, ValidateError, ValidateResult, WasmFinding, WasmFormatConfig, WasmLintConfig, WasmSeverity };
